import React from 'react';

import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList, { IPohListItem } from '@ui-kit/List';

import ArticleListItem from './ArticleListItem';
import { getArticlesAsync } from '../@services/articles.service';
import { IGetArticlesCriteria } from '../@types/articles.dto.types';
import { IArticle } from '../@types/articles.types';

interface IArticlesListProps extends IGetArticlesCriteria {
  listItemPatcher?: (article: IArticle) => Partial<IPohListItem>;
  withSearch?: boolean;
}

const ArticlesList = (props: IArticlesListProps = {}) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IArticle[]>([]);
  const [err, setErr] = React.useState<Error>();
  const [q, setQ] = React.useState('');

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);

        const criteria = { ...props };
        const dt = await getArticlesAsync(criteria);

        setData(dt);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [props]);
  const filteredData = React.useMemo(() => {
    if (!props.withSearch || !q.length) return data;
    return data.filter((x) => x.name.toLocaleLowerCase().includes(q.toLowerCase()));
  }, [data, q, props.withSearch]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!data.length) {
    return <Empty>Нет статей</Empty>;
  }

  return (
    <>
      <section>
        {!!props.withSearch && (
          <header className="pb-2">
            <PohInput type={InputTypes.search} value={q} onChange={setQ} placeholder="Найти" />
          </header>
        )}
        <div style={{ overflowY: 'auto', maxHeight: 400 }}>
          <PohList
            data={filteredData.map((x) => {
              return {
                key: x.id,
                children: <ArticleListItem article={x} />,
                ...(props.listItemPatcher ? props.listItemPatcher(x) : {}),
              };
            })}
          />
        </div>
      </section>
    </>
  );
};

export default ArticlesList;
